import type { Locale } from "../../src/core/types";
import type { StoryFact } from "../../src/core/story-update";
import type { GameContextInput } from "../../src/core/game-context";
import { roleSeed } from "../../src/core/story-role-binding";
import { storyWorld } from "./story-worlds";

// Gold labels and prose are explicit input, not generated by the scorer.
const settings=[
  {id:"workshop",ru:["кварц","медальон"],en:["quartz","medallion"]},
  {id:"fantasy",ru:["руна","амулет"],en:["rune","amulet"]},
  {id:"space",ru:["кислород","телеметрия"],en:["oxygen","telemetry"]},
  {id:"detective",ru:["улика","отпечаток"],en:["evidence","fingerprint"]},
  {id:"home",ru:["квитанция","альбом"],en:["receipt","album"]},
  {id:"survival",ru:["антидот","рация"],en:["antidote","radio"]},
] as const;
export function relevanceQualityCorpus(locale:Locale) {
  const ru=locale==="ru",s=(a:string,b:string)=>ru?a:b,N=s("Нора","Nora"),M=s("Мира","Mira");
  return settings.flatMap(setting=>{
    const [a,b]=setting[locale],w=storyWorld(locale,2);w.entities[0]!.name=N;w.entities[1]!.name=M;
    const source=s(`${N} записала подробности после долгого осмотра помещения, обсуждения расписания, проверки журналов и разговора с дежурным:`,`${N} recorded details after a lengthy inspection of the room, discussing the timetable, checking the logs and speaking to the attendant:`);
    const title=s(`${N} должна выполнить назначенное поручение после проверки расписания, согласования деталей, сверки журнала и разрешения дежурного: ${b}.`,`${N} must complete the assigned duty after checking the timetable, agreeing on details, reviewing the log and getting permission from the attendant: ${b}.`);
    const facts:StoryFact[]=[
      {kind:"belief",text:source+s(` безопасность «${a}» не подтверждена; доступ только при разрешении. Это мнение, не проверенный факт.`,` ${a} is safe only with permission; this is a belief, not a verified fact.`),quote:source+s(` безопасность «${a}» не подтверждена; доступ только при разрешении. Это мнение, не проверенный факт.`,` ${a} is safe only with permission; this is a belief, not a verified fact.`)},
      {kind:"event",text:s("Назначенное поручение выполнено, журнал подписан, квитанция выдана, сведения внесены в архив.","The assigned duty is complete, the log is signed, the receipt issued and the details filed in the archive."),quote:title+s(" Поручение выполнено."," The duty is complete."),task:{key:"opaque-duty-204b",title,status:"completed"}},
      {kind:"secret",text:s(`${N} раскрыла тайну: «${a}» находится в запертом шкафу, а не у Миры.`,`${N} disclosed a secret: ${a} is in the locked cupboard, not with ${M}.`),quote:s(`${N} раскрыла тайну: «${a}» находится в запертом шкафу, а не у Миры.`,`${N} disclosed a secret: ${a} is in the locked cupboard, not with ${M}.`)},
      {kind:"promise",text:s(`${N} обещала Мире помощь только после разрешения охраны.`,`${N} promised ${M} help only after the guards give permission.`),quote:s(`${N} сказала Мире: «Я обещаю помочь только после разрешения охраны».`,`${N} told ${M}: “I promise to help only after the guards give permission.”`),task:{key:"owned-help",title:s("помощь после разрешения охраны","help after the guards give permission"),status:"open"}},
    ];
    const noise:StoryFact[]=Array.from({length:20},(_,i)=>{const text=s(`${N} спросила, что известно, и попросила напомнить подробности разговора с Мирой у окна. Запись ${i}.`,`${N} asked what we know and requested a reminder of the conversation with ${M} by the window. Record ${i}.`);return {kind:"event",text,quote:text};});
    const sources=["old-selected-source",...noise.map((_,i)=>"later-source-"+i)],seeds=facts.map((f,i)=>roleSeed(f,{version:1,sourceRevisionId:sources[0]!,quote:f.quote,roles:i===3?{speaker:{id:w.entities[0]!.id,name:N},promisor:{id:w.entities[0]!.id,name:N},recipient:{id:w.entities[1]!.id,name:M}}:{}}));
    const cases=[
      {id:"late-body",query:s(`Что известно о Норе и «${a}»?`,`What do we know about ${N} and ${a}?`),gold:[0,2],first:0,critical:s("Это мнение, не проверенный факт","this is a belief, not a verified fact")},
      {id:"full-task-title",query:s(`Напомни о Норе и «${b}».`,`Remind me about ${N} and ${b}.`),gold:[1],first:1,critical:title},
      {id:"past-secret",query:s(`У Миры этого нет. Где «${a}»?`,`Where is ${a}, which is not with ${M}?`),gold:[2],first:2,critical:s("а не у Миры",`not with ${M}`)},
      {id:"owned-promise",query:s(`Напомни, что ${N} обещала Мире.`,`Remind me what ${N} promised ${M}.`),gold:[3],first:3,critical:facts[3]!.quote},
    ];
    return cases.map(c=>{
      // First two cases have a single topical target; the other old fact is
      // deliberately absent, so a first-candidate label is unambiguous.
      const active=c.id==="late-body"?[facts[0]!,facts[1]!,facts[3]!,...noise]:c.id==="full-task-title"?[facts[1]!,facts[3]!,...noise]:[...facts,...noise];
      const wanted=c.gold.filter(i=>active.includes(facts[i]!)).map(i=>facts[i]!),first=facts[c.first]!;
      const input:GameContextInput={draft:c.query,recentMessages:[],entries:[],books:[],entities:w.entities,worlds:[w.world],activeBookId:null,scene:{worldId:w.world.id,bookId:null,focusIds:[]},settings:{contextBudget:6000,relevanceThreshold:6},story:{world:w.world,chat:w.binding.chatId,branch:"quality-branch",facts:active,sheetsEnabled:false,roleSeeds:seeds,episodeSources:sources}};
      return {name:setting.id+":"+locale+":"+c.id,locale,input,wanted,first,critical:c.critical};
    });
  });
}
